def gloss_page(part):
    items = GLOSS[:30] if part == 0 else GLOSS[30:]
    def f(lang):
        cells = ''.join(f'<div style="break-inside:avoid;margin-bottom:2.1mm;font-size:8.6pt;line-height:1.42"><b style="font:500 10.5pt EBG">{esc(a if lang == "pt" else b)}</b> · {esc(c if lang == "pt" else d)}</div>' for a, b, c, d in items)
        return f'<div class="cols2">{cells}</div>'
    return f


def family_page(fam):
    return fam


def tasting_sheet(lang):
    fields = [('Chá / origem', 'Tea / origin'), ('Data · fornecedor', 'Date · supplier'), ('Folha seca (cor, forma, aroma)', 'Dry leaf (colour, shape, aroma)'),
              ('Preparo (g · ml · °C · tempo)', 'Brewing (g · ml · °C · time)'), ('Licor (cor, brilho)', 'Liquor (colour, clarity)'), ('Aroma', 'Aroma'),
              ('Sabor (doce, amargo, ácido, umami)', 'Taste (sweet, bitter, sour, umami)'), ('Textura e corpo', 'Texture and body'), ('Retrogosto', 'Aftertaste'),
              ('Folha molhada', 'Infused leaf'), ('Reinfusões', 'Resteeps'), ('Notas livres', 'Free notes')]
    scales = [('Doçura', 'Sweetness'), ('Adstringência', 'Astringency'), ('Intensidade', 'Intensity'), ('Nota geral', 'Overall')]
    return sheet(lang, fields, scales)


